        internal void Update()
        {

            if (Configuration.LISSettings.GetBool("ReportAnalyteBatching"))
            {
                Update_WithBatching();
            }
            else
            {
                Update_WithoutBatching();
            }


        }

        internal void Update_WithBatching()
        {

            var reportAnalyteTable = CreateReportAnalyteDataTable();
            var refAnalyteTable = CreateRefAnalyteDataTable();
            DataRow reportAnalyteRow, refAnalyteRow;
            var timer = new Stopwatch();
            timer.Start();
            foreach (ReportAnalyte a in List)
            {
                if (a.IsDirty)
                {
                    if (!updatedList.ContainsKey(a.Code))
                    {
                        updatedList.Add(a.Code, a);
                    }
                    reportAnalyteRow = reportAnalyteTable.NewRow();
                    a.GetUpdateRow(ref reportAnalyteRow);
                    reportAnalyteTable.Rows.Add(reportAnalyteRow);
                }
            }

            var dtOut = SaveReportAnalyteBatch(reportAnalyteTable);
            SetReportAnalyteId(dtOut);
            foreach (ReportAnalyte a in List)
            {
                if (a.IsDirty)
                {
                    if (!updatedRefAnalyteList.ContainsKey(a.Code))
                    {
                        updatedRefAnalyteList.Add(a.Code, (RefAnalyte)a.Analyte);
                    }
                    refAnalyteRow = refAnalyteTable.NewRow();
                    a.Update(ref refAnalyteRow);
                    if (refAnalyteRow is not null)
                    {
                        refAnalyteTable.Rows.Add(refAnalyteRow);
                    }
                }
            }

            var dtRefOut = SaveRefAnalyteBatch(refAnalyteTable);
            SetRefAnalyteId(dtRefOut);

            timer.Stop();
            object elapsedTime = timer.ElapsedMilliseconds;

            Log.DebugFormat("Call for batch Save ReportAnalyte took {0} milliseconds", elapsedTime);

            if (!(DeletedItemsList == null))
            {
                foreach (ReportAnalyte a in DeletedItemsList)
                {
                    if (a.IsNew == false)
                        a.Delete();
                }
                DeletedItemsList.Clear();
            }


        }
        internal void Update_WithoutBatching()
        {
            var timer = new Stopwatch();
            timer.Start();
            foreach (ReportAnalyte a in List)
            {
                if (a.IsDirty)
                {
                    a.Update();
                }
            }
            timer.Stop();
            object elapsedTime = timer.ElapsedMilliseconds;
            Log.DebugFormat("Total Time for Save ReportAnalyte without batch took {0} milliseconds", elapsedTime);

            if (!(DeletedItemsList == null))
            {
                foreach (ReportAnalyte a in DeletedItemsList)
                {
                    if (a.IsNew == false)
                        a.Delete();
                }
                DeletedItemsList.Clear();
            }

        }

        private void SetRefAnalyteId(DataTable dtRefOut)
        {
            if (dtRefOut is null || dtRefOut.Rows.Count == 0)
            {
                return;
            }
            foreach (DataRow dr in dtRefOut.Rows)
            {
                if (updatedRefAnalyteList.ContainsKey(Conversions.ToString(dr[1])))
                {
                    updatedRefAnalyteList[Conversions.ToString(dr[1])].SetRefAnalyteId(Conversions.ToLong(dr[0]));
                }
            }
        }

        private DataTable SaveRefAnalyteBatch(DataTable refAnalyteTable)
        {

            if (refAnalyteTable is null || refAnalyteTable.Rows.Count == 0)
            {
                return null;
            }
            var conn = new SqlConnection(Configuration.ConnectionString);
            SqlCommand cmd = null;
            var dtOut = new DataTable();
            SqlDataAdapter da;
            try
            {

                cmd = new SqlCommand();
                cmd.Connection = conn;
                cmd.CommandType = CommandType.StoredProcedure;
                cmd.CommandText = "lis_RefAnalyte_Batch_Save";

                cmd.Parameters.AddWithValue("@RefAnalyteTableType", SqlDbType.Structured).Value = refAnalyteTable;

                da = new SqlDataAdapter(cmd);
                da.Fill(dtOut);

                return dtOut;
            }
            catch (Exception ex)
            {
                throw;
            }
        }

