        public bool UnDeleteAnalyte(long analyteId)
        {

            foreach (ReportAnalyte a in ArchivedDeletedList)
            {
                if (a.ID == analyteId)
                {
                    return UnDeleteAnalyte(a);
                }
            }

            return default;

        }

        internal bool UnDeleteAnalyte(ReportAnalyte analyte)
        {

            // Check to see that the analyte doesn't already exist in active list.
            foreach (ReportAnalyte a in List)
            {
                // If a.ID = analyte.ID Then Return False
                if ((a.Code ?? "") == (analyte.Code ?? ""))
                    return false;
            }

            // Me.DeletedItemsList.Remove(analyte)
            analyte.FlagUnDeleted();
            List.Add(analyte);
            // Me.DeletedItemsList.Remove(analyte)
            return true;


        }

        public ReportAnalyte FindFirstDeleted(object analyteCode)
        {
            foreach (object o in ArchivedDeletedList)
            {
                if (Conversions.ToBoolean(Operators.ConditionalCompareObjectEqual(((ReportAnalyte)o).Code, analyteCode, false)))
                    return (ReportAnalyte)o;
            }
            return null;
        }


